// Release builds (Xcode archive) get a build number from the date and time, so that every upload
// to TestFlight is accepted without editing the project: CFBundleVersion = YYMMDD.HHMM (UTC),
// always increasing. Debug builds keep the number of the project. Written into the built
// Info.plist, before signing; ios/ is generated by prebuild, hence a config plugin.
const { withXcodeProject } = require('expo/config-plugins');

const PHASE = 'Daily Edge: build number from the date';
const SCRIPT = [
  'if [ "$CONFIGURATION" != "Release" ]; then exit 0; fi',
  'BUILD_NUMBER="$(date -u +%y%m%d).$(date -u +%H%M)"',
  'PLIST="$TARGET_BUILD_DIR/$INFOPLIST_PATH"',
  '/usr/libexec/PlistBuddy -c "Set :CFBundleVersion $BUILD_NUMBER" "$PLIST"',
  'echo "CFBundleVersion = $BUILD_NUMBER"',
].join('\n');

module.exports = function withAutoBuildNumber(config) {
  return withXcodeProject(config, (config) => {
    const project = config.modResults;
    if (project.pbxItemByComment(PHASE, 'PBXShellScriptBuildPhase')) return config;
    const target = project.getFirstTarget().uuid;
    project.addBuildPhase([], 'PBXShellScriptBuildPhase', PHASE, target, {
      shellPath: '/bin/sh',
      // addBuildPhase quotes the script and escapes its quotes, not its newlines
      shellScript: SCRIPT.replace(/\n/g, '\\n'),
      // Runs at every build (no inputs/outputs to compare)
      alwaysOutOfDate: 1,
    });
    return config;
  });
};
